1	import 'dart:async';
2	
3	import 'package:flutter/foundation.dart';
4	import 'package:flutter_bloc/flutter_bloc.dart';
5	
6	import '../../../auth/domain/repositories/session_repository.dart';
7	import '../../../chat/domain/repositories/chat_repository.dart';
8	import '../../../entries/domain/repositories/entries_repository.dart';
9	import '../../../vault/domain/repositories/vault_repository.dart';
10	import '../../domain/repositories/account_settings_repository.dart';
11	
12	/// Drives [AccountSettingsScreen]: just the one toggle's current value
13	/// (mirrored straight from [AccountSettingsRepository.biometricEnabledStream]
14	/// — the repository is the single source of truth, Boundaries) plus an
15	/// inline error message for a failed toggle.
16	class AccountSettingsState {
17	  const AccountSettingsState({
18	    required this.biometricEnabled,
19	    this.errorMessage,
20	    this.isSaving = false,
21	    this.displayName = '',
22	    this.email = '',
23	    this.isEditingName = false,
24	    this.nameDraft = '',
25	    this.isSavingName = false,
26	    this.nameErrorMessage,
27	    this.isLoggingOut = false,
28	  });
29	
30	  final bool biometricEnabled;
31	
32	  /// Set only once [AccountSettingsCubit.toggleBiometric]'s own PATCH call
33	  /// fails — the switch itself has already reverted via the repository's
34	  /// own stream by the time this is shown (I/O matrix: "Toggle fails ->
35	  /// switch reverts ... Failure.message shown inline").
36	  final String? errorMessage;
37	
38	  /// Review finding: `true` for the duration of one [toggleBiometric] call
39	  /// — `account_settings_screen.dart` disables the `Switch` while this is
40	  /// `true`, so a double-tap can never start a second, overlapping
41	  /// `setBiometricEnabled` call in the first place (the repository's own
42	  /// generation guard is the backstop for every other overlap this can't
43	  /// prevent, e.g. a boot fetch racing a toggle).
44	  final bool isSaving;
45	
46	  /// spec-8-3 — the profile name shown in display mode, read from
47	  /// `AccountSettingsRepository.currentDisplayName` at construction
48	  /// (Boundaries), then kept in sync by [AccountSettingsCubit.
49	  /// confirmEditingName]'s own success branch, which re-reads
50	  /// `_repository.currentDisplayName` on every save (code-review patch:
51	  /// the repository's own value echoes any backend-side normalization,
52	  /// which the locally-sent string alone would miss).
53	  final String displayName;
54	
55	  /// spec-8-3 — the account e-mail, read the same way as [displayName] and
56	  /// never written anywhere (not editable — "email is rejected").
57	  final String email;
58	
59	  /// spec-8-3 — `true` while the name is in its inline-editable form (the
60	  /// pencil icon has become a check). Boundaries: "startEditingName()
61	  /// (draft = current name)".
62	  final bool isEditingName;
63	
64	  /// spec-8-3 — the in-progress edit's own text, separate from
65	  /// [displayName] until [AccountSettingsCubit.confirmEditingName] commits
66	  /// it. Kept exactly as typed (not trimmed) so a failed save redisplays
67	  /// the same text the user left in the field (Boundaries: "draft kept").
68	  final String nameDraft;
69	
70	  /// spec-8-3 — `true` for the duration of one
71	  /// [AccountSettingsCubit.confirmEditingName] PATCH call. Mirrors
72	  /// [isSaving]'s own role for the biometric toggle, kept as its own field
73	  /// (Boundaries: "never: merging name-edit into the toggle's own state").
74	  final bool isSavingName;
75	
76	  /// spec-8-3 — set only once [AccountSettingsCubit.confirmEditingName]'s
77	  /// own PATCH call fails; the field stays editable with [nameDraft]
78	  /// unchanged (I/O matrix: "Failure -> stays editing, inline error, draft
79	  /// kept").
80	  final String? nameErrorMessage;
81	
82	  /// Story 8.4 — `true` for the duration of one
83	  /// [AccountSettingsCubit.logout] call, guarding against re-entry
84	  /// (double-tap no-ops, Boundaries) — `account_settings_screen.dart`
85	  /// disables the "Sair" button while this is `true`, same convention
86	  /// [isSaving]/[isSavingName] already use for their own in-flight calls.
87	  final bool isLoggingOut;
88	
89	  AccountSettingsState copyWith({
90	    bool? biometricEnabled,
91	    String? errorMessage,
92	    bool clearErrorMessage = false,
93	    bool? isSaving,
94	    String? displayName,
95	    String? email,
96	    bool? isEditingName,
97	    String? nameDraft,
98	    bool? isSavingName,
99	    String? nameErrorMessage,
100	    bool clearNameErrorMessage = false,
101	    bool? isLoggingOut,
102	  }) {
103	    return AccountSettingsState(
104	      biometricEnabled: biometricEnabled ?? this.biometricEnabled,
105	      errorMessage: clearErrorMessage
106	          ? null
107	          : (errorMessage ?? this.errorMessage),
108	      isSaving: isSaving ?? this.isSaving,
109	      displayName: displayName ?? this.displayName,
110	      email: email ?? this.email,
111	      isEditingName: isEditingName ?? this.isEditingName,
112	      nameDraft: nameDraft ?? this.nameDraft,
113	      isSavingName: isSavingName ?? this.isSavingName,
114	      nameErrorMessage: clearNameErrorMessage
115	          ? null
116	          : (nameErrorMessage ?? this.nameErrorMessage),
117	      isLoggingOut: isLoggingOut ?? this.isLoggingOut,
118	    );
119	  }
120	
121	  @override
122	  bool operator ==(Object other) =>
123	      identical(this, other) ||
124	      (other is AccountSettingsState &&
125	          other.biometricEnabled == biometricEnabled &&
126	          other.errorMessage == errorMessage &&
127	          other.isSaving == isSaving &&
128	          other.displayName == displayName &&
129	          other.email == email &&
130	          other.isEditingName == isEditingName &&
131	          other.nameDraft == nameDraft &&
132	          other.isSavingName == isSavingName &&
133	          other.nameErrorMessage == nameErrorMessage &&
134	          other.isLoggingOut == isLoggingOut);
135	
136	  @override
137	  int get hashCode => Object.hash(
138	    biometricEnabled,
139	    errorMessage,
140	    isSaving,
141	    displayName,
142	    email,
143	    isEditingName,
144	    nameDraft,
145	    isSavingName,
146	    nameErrorMessage,
147	    isLoggingOut,
148	  );
149	
150	  @override
151	  String toString() =>
152	      'AccountSettingsState(biometricEnabled: $biometricEnabled, '
153	      'errorMessage: $errorMessage, isSaving: $isSaving, '
154	      'displayName: $displayName, email: $email, '
155	      'isEditingName: $isEditingName, nameDraft: $nameDraft, '
156	      'isSavingName: $isSavingName, nameErrorMessage: $nameErrorMessage, '
157	      'isLoggingOut: $isLoggingOut)';
158	}
159	
160	/// Calls [AccountSettingsRepository] directly (no use-case — same small-
161	/// scope rationale `AuthCubit`'s own doc gives). [toggleBiometric] is the
162	/// I/O matrix's optimistic flip/revert, end to end: the repository itself
163	/// flips [AccountSettingsRepository.currentBiometricEnabled] immediately
164	/// and emits it on [AccountSettingsRepository.biometricEnabledStream] —
165	/// this cubit only mirrors that stream into its own [AccountSettingsState]
166	/// (subscribed once, at construction) and separately layers the
167	/// toggle-failure error message on top.
168	class AccountSettingsCubit extends Cubit<AccountSettingsState> {
169	  AccountSettingsCubit(
170	    this._repository,
171	    this._sessionRepository,
172	    this._vaultRepository,
173	    this._entriesRepository,
174	    this._chatRepository,
175	  ) : super(
176	        AccountSettingsState(
177	          biometricEnabled: _repository.currentBiometricEnabled,
178	          // spec-8-3 — read once, at construction (Boundaries); never
179	          // re-read from the repository afterwards.
180	          displayName: _repository.currentDisplayName,
181	          email: _repository.currentEmail,
182	        ),
183	      ) {
184	    _subscription = _repository.biometricEnabledStream.listen((value) {
185	      // Review finding: `biometricEnabledStream`'s first delivery always
186	      // replays the exact same value the constructor above just read
187	      // synchronously — without this check, that replay was a redundant
188	      // duplicate emission (not skipped by `Cubit`'s own equal-state dedup,
189	      // which only applies once something has already been emitted),
190	      // forcing one pointless extra rebuild right after every screen mount.
191	      if (value == state.biometricEnabled) {
192	        return;
193	      }
194	      emit(state.copyWith(biometricEnabled: value));
195	    });
196	  }
197	
198	  final AccountSettingsRepository _repository;
199	
200	  // Story 8.4 — direct-domain-interface deps, same precedent
201	  // `EntryDetailCubit`'s own `SessionRepository` param already sets (no
202	  // dedicated logout use-case; RNF06 is still satisfied since all four are
203	  // domain-layer abstractions).
204	  final SessionRepository _sessionRepository;
205	  final VaultRepository _vaultRepository;
206	  final EntriesRepository _entriesRepository;
207	  final ChatRepository _chatRepository;
208	
209	  late final StreamSubscription<bool> _subscription;
210	
211	  Future<void> toggleBiometric(bool value) async {
212	    emit(state.copyWith(clearErrorMessage: true, isSaving: true));
213	    final result = await _repository.setBiometricEnabled(value);
214	    // Review finding: this cubit is a `get_it` lazy singleton with
215	    // `dispose: (cubit) => cubit.close()` — if `close()` runs while the
216	    // `await` above is still pending (e.g. `resetCoreDependencies()`
217	    // during a logout, once Epic 8 implements one), `emit()` below would
218	    // otherwise throw a `StateError` ("Cannot emit new states after
219	    // calling close"), unlike the repository-layer `_emit` methods in this
220	    // codebase, which already guard against the equivalent race.
221	    if (isClosed) {
222	      return;
223	    }
224	    result.match((failure) {
225	      // Review finding: a superseded call's `Left` is an internal
226	      // control-flow signal (`AccountSettingsRepository.
227	      // supersededMessage`), not a real error — the winning call already
228	      // settled the value correctly, so nothing should be shown; showing
229	      // `failure.message` unconditionally leaked that raw, English,
230	      // internal string into this otherwise fully Portuguese screen.
231	      if (failure.message == AccountSettingsRepository.supersededMessage) {
232	        emit(state.copyWith(isSaving: false));
233	        return;
234	      }
235	      emit(state.copyWith(errorMessage: failure.message, isSaving: false));
236	    }, (_) => emit(state.copyWith(isSaving: false)));
237	  }
238	
239	  /// Review finding: [errorMessage] previously cleared only at the start of
240	  /// the *next* [toggleBiometric] call — since this cubit is a DI
241	  /// singleton that outlives any single Configurações visit, a failed
242	  /// toggle's error text would otherwise still be showing if the user
243	  /// left the screen and came back later with no new attempt made.
244	  /// `account_settings_screen.dart` calls this once, on mount, same
245	  /// "stale message must not linger unchanged" fix already applied to
246	  /// `vault_lock_screen.dart`'s own PIN-mismatch error, just anchored to
247	  /// screen-entry instead of attempt-start.
248	  void clearStaleError() {
249	    if (state.errorMessage != null) {
250	      emit(state.copyWith(clearErrorMessage: true));
251	    }
252	  }
253	
254	  /// spec-8-3 — tapping the pencil icon (I/O matrix: "Tap pencil ->
255	  /// `isEditingName: false` -> Field replaces name, draft = current, icon
256	  /// -> check"). Also clears any leftover [AccountSettingsState.
257	  /// nameErrorMessage] from a previous failed attempt.
258	  void startEditingName() {
259	    emit(
260	      state.copyWith(
261	        isEditingName: true,
262	        nameDraft: state.displayName,
263	        clearNameErrorMessage: true,
264	      ),
265	    );
266	  }
267	
268	  /// spec-8-3 — mirrors the field's own `onChanged`, kept as the single
269	  /// source [confirmEditingName] reads from.
270	  void updateNameDraft(String value) {
271	    emit(state.copyWith(nameDraft: value));
272	  }
273	
274	  /// spec-8-3 — I/O matrix: "Tap away, not saving -> Reverts, draft
275	  /// discarded, no PATCH" / "Tap away, saving -> No-op, save completes".
276	  /// A no-op while [AccountSettingsState.isSavingName] (Boundaries) — the
277	  /// in-flight [confirmEditingName] call owns the eventual transition back
278	  /// to display mode.
279	  void cancelEditingName() {
280	    if (state.isSavingName) {
281	      return;
282	    }
283	    emit(state.copyWith(isEditingName: false, clearNameErrorMessage: true));
284	  }
285	
286	  /// spec-8-3 — tapping the check icon. Trims [AccountSettingsState.
287	  /// nameDraft] only for the empty/unchanged comparison and the PATCH
288	  /// payload itself; an empty or unchanged draft reverts immediately with
289	  /// no PATCH (I/O matrix). Otherwise awaits
290	  /// `AccountSettingsRepository.setDisplayName` (not optimistic,
291	  /// Boundaries) — success reverts to display mode showing the new name;
292	  /// failure stays in edit mode with the draft kept and an inline error.
293	  Future<void> confirmEditingName() async {
294	    final trimmed = state.nameDraft.trim();
295	    if (trimmed.isEmpty || trimmed == state.displayName) {
296	      emit(state.copyWith(isEditingName: false, clearNameErrorMessage: true));
297	      return;
298	    }
299	    emit(state.copyWith(isSavingName: true, clearNameErrorMessage: true));
300	    final result = await _repository.setDisplayName(trimmed);
301	    // Same close()-race guard as toggleBiometric's own.
302	    if (isClosed) {
303	      return;
304	    }
305	    result.match(
306	      (failure) {
307	        // Same superseded-message filtering convention as toggleBiometric's
308	        // own failure branch — an internal control-flow signal, not a real
309	        // error to show.
310	        if (failure.message == AccountSettingsRepository.supersededMessage) {
311	          emit(state.copyWith(isSavingName: false));
312	          return;
313	        }
314	        emit(
315	          state.copyWith(
316	            isSavingName: false,
317	            nameErrorMessage: failure.message,
318	          ),
319	        );
320	      },
321	      (_) {
322	        // Review finding: reads the repository's own echoed value (set
323	        // from `dto.displayName` in `setDisplayName`'s success branch),
324	        // not the locally-sent `trimmed` string — any backend-side
325	        // normalization (trimming, casing, etc.) must reach this state,
326	        // the one place the user actually sees the name, not just the
327	        // repository's own internal cache.
328	        emit(
329	          state.copyWith(
330	            isEditingName: false,
331	            isSavingName: false,
332	            displayName: _repository.currentDisplayName,
333	            clearNameErrorMessage: true,
334	          ),
335	        );
336	      },
337	    );
338	  }
339	
340	  /// Story 8.4 — the "Sair" button's whole flow, end to end. Guards
341	  /// re-entry via [AccountSettingsState.isLoggingOut] (Boundaries: a
342	  /// double-tap no-ops). [VaultRepository.lock] fires synchronously
343	  /// BEFORE awaiting [SessionRepository.logout] (Boundaries) — AD-14's
344	  /// vault-gate-first redirect then lands on `/vault` immediately, with no
345	  /// transient `/auth` hop, while the backend call and the local cache
346	  /// clears still happen in the background. The session logout's own
347	  /// result is ignored (Boundaries: "local session already ended
348	  /// regardless") — it must never surface a backend-logout-failure error
349	  /// (Never). Same `isClosed` guard as [toggleBiometric].
350	  Future<void> logout() async {
351	    if (state.isLoggingOut) {
352	      return;
353	    }
354	    emit(state.copyWith(isLoggingOut: true));
355	    try {
356	      _vaultRepository.lock();
357	      await _sessionRepository.logout();
358	      // Review finding: neither result was ever inspected — a cache-clear
359	      // failure (e.g. Hive disk-full) was silently swallowed with zero
360	      // record anywhere. `debugPrint`-only (never surfaced to the UI, same
361	      // "no UI-visible error" boundary the session-logout call itself
362	      // follows), mirroring this codebase's existing silent-swallow-with-
363	      // debugPrint convention (`ApiClient.postStream`/`HeaderInterceptor`).
364	      final cacheResults = await Future.wait([
365	        _entriesRepository.clearLocalCache(),
366	        _chatRepository.clearLocalCache(),
367	      ]);
368	      // Code-review patch: tags each failure with its source repository —
369	      // an untagged message would make a real disk-full failure
370	      // unattributable from logs alone.
371	      const cacheSources = ['entries', 'chat'];
372	      for (var i = 0; i < cacheResults.length; i++) {
373	        cacheResults[i].match(
374	          (failure) => debugPrint(
375	            'AccountSettingsCubit.logout: ${cacheSources[i]}.'
376	            'clearLocalCache failed — ${failure.message}',
377	          ),
378	          (_) {},
379	        );
380	      }
381	    } finally {
382	      // Code-review patch: guarantees `isLoggingOut` resets even if an
383	      // unexpected throw escapes the chain above (none currently do, but
384	      // nothing enforces that) — without this, such a throw would leave
385	      // the "Sair" button permanently disabled.
386	      if (!isClosed) {
387	        emit(state.copyWith(isLoggingOut: false));
388	      }
389	    }
390	  }
391	
392	  @override
393	  Future<void> close() async {
394	    await _subscription.cancel();
395	    return super.close();
396	  }
397	}
