    return result.match((failure) {
      // Revert on failure — the caller surfaces `failure.message` inline.
      _emit(previous);
      return left(failure);
    }, (_) => right(unit));
  }

  @override
  Future<void> dispose() async {
    await _controller.close();
  }
}

